head.script:
/* =====================================================================
 * KHÁCH MỜI - IMPORT DANH SÁCH (wizard: chọn file -> kiểm tra & mapping -> kết quả)
 * API: /api/guests/import (xem API_GUEST.md mục 6)
 * ===================================================================== */
scwin.P = "gs";
/* =====================================================================
 * LỚP DÙNG CHUNG (giống các màn Hội trường / Sự kiện)
 *   - Phiên đăng nhập, quyền
 *   - Gọi API JSON bằng submission WebSquare (scwin.callApi)
 *   - Upload / tải file bằng XMLHttpRequest (submission không xử lý file nhị phân)
 * ===================================================================== */
scwin.API_BASE = "http://localhost:8081";
scwin.KEY = { TOKEN: "ssc_token", USER: "ssc_user", PERMS: "ssc_permissions", MENUS: "ssc_menus" };
scwin.LOGIN_PAGE = "/authPage/LoginPage.xml";
scwin.CTX = window.location.pathname.replace(/\/websquare\/websquare\.html.*$/, "");
scwin.SBM_TIMEOUT = 60000;
scwin.sbmQueue = {};
scwin.sbmJob = {};
scwin.toastTimer = null;

/* ---------- Tiện ích ---------- */
scwin.comp = function (id) { return $p.getComponentById(id); };
scwin.domOf = function (c) { return c ? (c.render || document.getElementById(c.id) || null) : null; };
scwin.show = function (c, v) { if (!c) return; if (v === false) c.addClass("is-hidden"); else c.removeClass("is-hidden"); };
scwin.toggleClass = function (c, cls, on) { if (!c) return; if (on) c.addClass(cls); else c.removeClass(cls); };
scwin.safeColor = function (c) { return /^#[0-9a-f]{3,8}$/i.test(String(c || "")) ? c : "#63746b"; };
scwin.trim = function (v) { return v == null ? "" : String(v).replace(/^\s+|\s+$/g, ""); };
scwin.dash = function (v) { return (v == null || scwin.trim(v) === "") ? "—" : String(v); };
scwin.pad = function (n) { return n < 10 ? "0" + n : String(n); };
scwin.clamp = function (v, a, b) { v = Number(v) || 0; a = a == null ? 0 : a; b = b == null ? 100 : b; return Math.max(a, Math.min(b, v)); };
scwin.hasOwn = function (o, k) { return o != null && Object.prototype.hasOwnProperty.call(o, k); };
scwin.fmtNumber = function (n) { return (n == null || n === "" || isNaN(Number(n))) ? "—" : Number(n).toLocaleString("vi-VN"); };
scwin.fmtRate = function (r) { return (Math.round((Number(r) || 0) * 10) / 10).toLocaleString("vi-VN") + "%"; };
scwin.fmtDate = function (s) { if (!s) return ""; var p = String(s).substring(0, 10).split("-"); return p.length === 3 ? p[2] + "/" + p[1] + "/" + p[0] : String(s); };
scwin.fmtTime = function (s) { return s ? String(s).substring(0, 5) : ""; };
scwin.fmtDateTime = function (iso) {
    if (!iso) return "—";
    var d = new Date(iso);
    if (isNaN(d.getTime())) return String(iso);
    return scwin.pad(d.getDate()) + "/" + scwin.pad(d.getMonth() + 1) + "/" + d.getFullYear() + " " + scwin.pad(d.getHours()) + ":" + scwin.pad(d.getMinutes());
};
scwin.fmtClock = function (iso) {
    var d = iso ? new Date(iso) : new Date();
    if (isNaN(d.getTime())) d = new Date();
    return scwin.pad(d.getHours()) + ":" + scwin.pad(d.getMinutes()) + ":" + scwin.pad(d.getSeconds());
};
scwin.fmtSize = function (b) { return b >= 1048576 ? (b / 1048576).toFixed(1) + " MB" : Math.max(1, Math.round(b / 1024)) + " KB"; };
/** Tham số mảng được nối bằng dấu phẩy (backend nhận cả "A,B" lẫn lặp tham số). */
scwin.buildQuery = function (p) {
    var out = [];
    for (var k in p) {
        if (!p.hasOwnProperty(k)) continue;
        var v = p[k];
        if (Array.isArray(v)) { if (!v.length) continue; v = v.join(","); }
        if (v === null || v === undefined || v === "") continue;
        out.push(encodeURIComponent(k) + "=" + encodeURIComponent(v));
    }
    return out.join("&");
};
scwin.getQueryParam = function (name) {
    var m = new RegExp("[?&]" + name + "=([^&#]*)").exec(window.location.search);
    return m ? decodeURIComponent(m[1].replace(/\+/g, " ")) : "";
};
scwin.pageUrl = function (path, params) {
    var q = params ? scwin.buildQuery(params) : "";
    return scwin.CTX + "/websquare/websquare.html?w2xPath=" + scwin.CTX + path + (q ? "&" + q : "");
};
scwin.escHtml = function (s) { return String(s == null ? "" : s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;"); };
scwin.el = function (tag, cls, text) { var e = document.createElement(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; return e; };
scwin.clearEl = function (el) { if (el) while (el.firstChild) el.removeChild(el.firstChild); };
scwin.fitGrid = function (grid, rows, rowH, maxRows) {
    var n = maxRows ? Math.min(rows, maxRows) : rows;
    grid.setStyle("height", (rows ? 42 + n * (rowH || 46) + 2 : 0) + "px");
    scwin.show(grid, rows > 0);
};
scwin.isTrue = function (v) { return v === true || v === "true" || v === 1 || v === "1"; };

/* ---------- Phiên đăng nhập & quyền ---------- */
scwin.storeGet = function (k) { try { return window.localStorage.getItem(k) || window.sessionStorage.getItem(k) || ""; } catch (e) { return ""; } };
scwin.parseJSON = function (t) { if (!t || typeof t !== "string") return null; try { return JSON.parse(t); } catch (e) { return null; } };
scwin.getToken = function () { return String(scwin.storeGet(scwin.KEY.TOKEN)).replace(/^Bearer\s+/i, ""); };
scwin.getPerms = function () { return scwin.parseJSON(scwin.storeGet(scwin.KEY.PERMS)) || []; };
scwin.getUser = function () { return scwin.parseJSON(scwin.storeGet(scwin.KEY.USER)) || {}; };
/** Header chưa kịp lưu quyền (lần đầu vào trang) thì tạm cho phép; backend vẫn chặn bằng 403. */
scwin.can = function (code) { var p = scwin.getPerms(); return !p.length || p.indexOf(code) >= 0; };
scwin.canAny = function (codes) { for (var i = 0; i < codes.length; i++) if (scwin.can(codes[i])) return true; return false; };
scwin.goLogin = function () {
    if (scwin._redirecting) return;
    scwin._redirecting = true;
    for (var k in scwin.KEY) {
        if (!scwin.KEY.hasOwnProperty(k)) continue;
        try { window.localStorage.removeItem(scwin.KEY[k]); window.sessionStorage.removeItem(scwin.KEY[k]); } catch (e) { }
    }
    window.location.href = scwin.pageUrl(scwin.LOGIN_PAGE);
};

/* ---------- Lỗi ---------- */
scwin.defaultMessage = function (status) {
    if (status === 0) return "Không kết nối được máy chủ. Kiểm tra mạng hoặc backend (" + scwin.API_BASE + ").";
    if (status === 401) return "Phiên đăng nhập đã hết hạn. Hãy đăng nhập lại.";
    if (status === 403) return "Tài khoản của bạn chưa được cấp quyền cho thao tác này.";
    if (status === 404) return "Không tìm thấy dữ liệu, hoặc dữ liệu nằm ngoài phạm vi bạn được xem.";
    if (status >= 500) return "Máy chủ đang gặp sự cố. Thử lại sau ít phút.";
    return "Yêu cầu không thành công (HTTP " + status + ").";
};
scwin.authHeader = function (accept) {
    var h = { "Accept": accept || "application/json" };
    var t = scwin.getToken();
    if (t) h["Authorization"] = "Bearer " + t;
    return h;
};
/** Chuẩn hóa lỗi: { status, code, message, data }. 401 thì đưa về trang đăng nhập. */
scwin.buildError = function (status, json) {
    var err = {
        status: status || 0,
        code: (json && json.code) || (status ? "HTTP_" + status : "NETWORK_ERROR"),
        message: (json && json.message) || scwin.defaultMessage(status || 0),
        data: json ? json.data : null
    };
    if (status === 401) {
        err.message = scwin.defaultMessage(401);
        scwin.toast(err.message + " Đang chuyển về trang đăng nhập…", "error");
        setTimeout(scwin.goLogin, 1500);
    }
    return err;
};

/* ---------- Submission ----------
 *   scwin.callApi("sbm_xxx", { url: "...", body: {...} }) -> Promise<data>
 *   Mỗi submission có hàng đợi riêng nên gọi chồng nhau không bị trả nhầm kết quả.
 */
scwin.callApi = function (sbmId, opts) {
    return new Promise(function (resolve, reject) {
        if (!scwin.sbmQueue[sbmId]) scwin.sbmQueue[sbmId] = [];
        scwin.sbmQueue[sbmId].push({ opts: opts || {}, resolve: resolve, reject: reject });
        scwin.sbmNext(sbmId);
    });
};
scwin.sbmNext = function (sbmId) {
    if (scwin.sbmJob[sbmId]) return;
    var q = scwin.sbmQueue[sbmId];
    if (!q || !q.length) return;
    var job = q.shift();
    scwin.sbmJob[sbmId] = job;
    var sbm = $p.getSubmission(sbmId);
    if (!sbm) { scwin.sbmSettle(sbmId, null, { status: 0, code: "SUBMISSION_NOT_FOUND", message: "Chưa khai báo submission " + sbmId + "." }); return; }
    sbm.action = job.opts.url;
    sbm.requestHeader = scwin.authHeader();
    job.timer = setTimeout(function () {
        scwin.sbmSettle(sbmId, null, { status: 0, code: "TIMEOUT", message: "Máy chủ phản hồi quá lâu. Thử lại sau." });
    }, scwin.SBM_TIMEOUT);
    try {
        if (job.opts.body !== undefined) $p.executeSubmission(sbmId, job.opts.body);
        else $p.executeSubmission(sbmId);
    } catch (ex) {
        scwin.sbmSettle(sbmId, null, { status: 0, code: "SUBMISSION_ERROR", message: (ex && ex.message) || String(ex) });
    }
};
scwin.sbmSettle = function (sbmId, data, err) {
    var job = scwin.sbmJob[sbmId];
    if (!job) return;
    clearTimeout(job.timer);
    scwin.sbmJob[sbmId] = null;
    if (err) job.reject(err); else job.resolve(data);
    scwin.sbmNext(sbmId);
};
scwin.readResponse = function (e) {
    if (!e) return null;
    if (e.responseJSON && typeof e.responseJSON === "object") return e.responseJSON;
    return scwin.parseJSON(e.responseText) || scwin.parseJSON(e.responseBody);
};
scwin.onSbmDone = function (sbmId, e) {
    var json = scwin.readResponse(e);
    if (json && json.success === false) { scwin.sbmSettle(sbmId, null, scwin.buildError((e && e.responseStatusCode) || 200, json)); return; }
    scwin.sbmSettle(sbmId, scwin.hasOwn(json, "data") ? json.data : json, null);
};
scwin.onSbmError = function (sbmId, e) {
    var status = (e && (e.responseStatusCode || e.status)) || 0;
    scwin.sbmSettle(sbmId, null, scwin.buildError(status, scwin.readResponse(e)));
};

/* ---------- XMLHttpRequest: upload multipart, nhận file ----------
 *   opts.body: object (gửi JSON) | FormData (multipart)
 *   opts.responseType: "json" (mặc định) | "blob" -> resolve { blob, name, type, headers }
 */
scwin.xhr = function (method, url, opts) {
    opts = opts || {};
    return new Promise(function (resolve, reject) {
        var x = new XMLHttpRequest();
        x.open(method, url);
        var h = scwin.authHeader(opts.responseType === "blob" ? "*/*" : "application/json");
        for (var k in h) if (h.hasOwnProperty(k)) x.setRequestHeader(k, h[k]);
        var body = null;
        if (typeof FormData !== "undefined" && opts.body instanceof FormData) body = opts.body;
        else if (opts.body !== undefined && opts.body !== null) { x.setRequestHeader("Content-Type", "application/json"); body = JSON.stringify(opts.body); }
        if (opts.responseType === "blob") x.responseType = "blob";
        if (opts.onProgress && x.upload) x.upload.onprogress = function (ev) { if (ev.lengthComputable) opts.onProgress(Math.round(ev.loaded * 100 / ev.total)); };
        x.onload = function () {
            var ok = x.status >= 200 && x.status < 300;
            if (opts.responseType === "blob") {
                var type = x.getResponseHeader("Content-Type") || "";
                if (ok && type.indexOf("application/json") < 0) {
                    resolve({ blob: x.response, type: type, name: scwin.fileNameFrom(x.getResponseHeader("Content-Disposition")), xhr: x });
                    return;
                }
                scwin.readBlobJSON(x.response).then(function (json) { reject(scwin.buildError(ok ? 200 : x.status, json)); });
                return;
            }
            var json = scwin.parseJSON(x.responseText);
            if (ok && !(json && json.success === false)) resolve(scwin.hasOwn(json, "data") ? json.data : json);
            else reject(scwin.buildError(x.status, json));
        };
        x.onerror = function () { reject(scwin.buildError(0, null)); };
        x.send(body);
    });
};
scwin.readBlobJSON = function (blob) {
    return new Promise(function (resolve) {
        if (!blob || typeof FileReader === "undefined") { resolve(null); return; }
        var r = new FileReader();
        r.onload = function () { resolve(scwin.parseJSON(r.result)); };
        r.onerror = function () { resolve(null); };
        r.readAsText(blob);
    });
};
scwin.fileNameFrom = function (cd) {
    if (!cd) return "";
    var m = /filename\*=UTF-8''([^;]+)/i.exec(cd) || /filename="?([^";]+)"?/i.exec(cd);
    if (!m) return "";
    try { return decodeURIComponent(m[1]); } catch (e) { return m[1]; }
};
scwin.saveBlob = function (blob, name) {
    var url = URL.createObjectURL(blob);
    var a = scwin.el("a", scwin.P + "-native-link");
    a.href = url; a.download = name;
    document.body.appendChild(a); a.click();
    setTimeout(function () { URL.revokeObjectURL(url); if (a.parentNode) a.parentNode.removeChild(a); }, 1500);
};
/** Tải file (GET hoặc POST kèm body JSON) rồi lưu về máy. */
scwin.downloadFile = function (url, fallbackName, btn, method, body) {
    if (btn) btn.addClass("is-busy");
    return scwin.xhr(method || "GET", url, { responseType: "blob", body: body }).then(function (r) {
        scwin.saveBlob(r.blob, r.name || fallbackName);
        return r;
    }).catch(function (err) {
        scwin.toast(err.message, "error");
        throw err;
    }).then(function (r) { if (btn) btn.removeClass("is-busy"); return r; }, function () { if (btn) btn.removeClass("is-busy"); });
};
/** In file PDF: nạp vào iframe ẩn rồi mở hộp thoại in của trình duyệt. */
scwin.printBlob = function (blob) {
    return new Promise(function (resolve) {
        var old = document.getElementById("ssc-print-frame");
        if (old) old.parentNode.removeChild(old);
        var url = URL.createObjectURL(blob);
        var f = document.createElement("iframe");
        f.id = "ssc-print-frame";
        f.className = scwin.P + "-print-frame";
        f.src = url;
        f.onload = function () {
            setTimeout(function () {
                try { f.contentWindow.focus(); f.contentWindow.print(); }
                catch (e) { window.open(url, "_blank"); }
                resolve();
            }, 300);
        };
        document.body.appendChild(f);
    });
};

/* ---------- Thông báo ---------- */
scwin.toast = function (msg, type) {
    if (typeof tbx_toast === "undefined") return;
    clearTimeout(scwin.toastTimer);
    tbx_toast.setValue(msg || "");
    ["success", "error", "warning", "info"].forEach(function (c) { tbx_toast.removeClass(scwin.P + "-toast--" + c); });
    tbx_toast.addClass(scwin.P + "-toast--" + (type || "info"));
    tbx_toast.addClass("is-show");
    scwin.toastTimer = setTimeout(function () { tbx_toast.removeClass("is-show"); }, (type === "error" || type === "warning") ? 6500 : 3800);
};
scwin.tbx_toast_onclick = function () { tbx_toast.removeClass("is-show"); };
scwin.showWarnings = function (list) {
    if (!list || !list.length) return;
    setTimeout(function () { scwin.toast("Lưu ý: " + list.join(" "), "warning"); }, 1800);
};

/* ---------- Danh mục dùng chung: GET /api/guests/lookups ---------- */
scwin.lookups = { events: [], guestTypes: [], guestStatuses: [] };
scwin.typeMeta = function (code) {
    for (var i = 0; i < scwin.lookups.guestTypes.length; i++) if (scwin.lookups.guestTypes[i].code === code) return scwin.lookups.guestTypes[i];
    return { code: code, name: code || "—", color: "#9E9E9E" };
};
scwin.statusMeta = function (code) {
    for (var i = 0; i < scwin.lookups.guestStatuses.length; i++) if (scwin.lookups.guestStatuses[i].code === code) return scwin.lookups.guestStatuses[i];
    return { code: code, name: code || "—", color: "#9E9E9E" };
};
scwin.GUEST_TYPE_VN = { VIP: "VIP", SPEAKER: "Diễn giả", GUEST: "Khách mời", STAFF: "Nhân viên", PRESS: "Báo chí", OTHER: "Khác" };
scwin.GUEST_STATUS_VN = { INVITED: "Đã mời", CONFIRMED: "Đã xác nhận", CHECKED_IN: "Đã check-in", ABSENT: "Vắng mặt" };
scwin.typeName = function (code) { return scwin.GUEST_TYPE_VN[code] || scwin.typeMeta(code).name; };
scwin.statusName = function (code) { return scwin.GUEST_STATUS_VN[code] || scwin.statusMeta(code).name; };
scwin.eventLabel = function (e) { return e.eventCode + " - " + e.eventName + (e.startDate ? " (" + scwin.fmtDate(e.startDate) + ")" : ""); };


scwin.GUEST_API = scwin.API_BASE + "/api/guests";
scwin.IMPORT_API = scwin.GUEST_API + "/import";
scwin.LIST_PAGE = "/guestPage/GuestList.xml";
scwin.MAX_FILE = 10 * 1024 * 1024;
scwin.EXTS = ["xlsx", "xls", "csv"];
scwin.MAP_FIELDS = [
    { key: "fullName", label: "Họ tên", required: true },
    { key: "email", label: "Email", required: true },
    { key: "phone", label: "Điện thoại" },
    { key: "company", label: "Công ty" },
    { key: "position", label: "Chức vụ" },
    { key: "guestType", label: "Loại khách" },
    { key: "tableNumber", label: "Bàn số" },
    { key: "notes", label: "Ghi chú" }
];
scwin.BATCH_STATUS_VN = { PENDING: "Chờ xác nhận", COMPLETED: "Hoàn tất", CANCELLED: "Đã hủy", FAILED: "Lỗi" };

scwin.file = null;
scwin.batch = null;           // kết quả preview đang xem
scwin.result = null;          // kết quả sau khi xác nhận
scwin.rowFilter = "all";
scwin.step = 1;
scwin.busy = false;

/* ---------- Vòng đời ---------- */
scwin.onpageload = function () {
    if (!scwin.getToken()) { scwin.goLogin(); return; }
    dma_import.setJSON({ eventId: scwin.getQueryParam("eventId"), skipErrors: "" });
    scwin.initFileInput();
    scwin.initDropzone();
    scwin.setStep(1);
    scwin.loadLookups();
};
scwin.onpageunload = function () {
    // Rời trang khi batch còn chờ xác nhận -> hủy để không treo batch
    if (scwin.batch && !scwin.result) scwin.cancelBatch(scwin.batch.batchId, true);
};

scwin.loadLookups = function () {
    scwin.callApi("sbm_lookups", { url: scwin.GUEST_API + "/lookups" }).then(function (d) {
        scwin.lookups.events = (d && d.events) || [];
        dlt_events.setJSON(scwin.lookups.events.filter(function (e) { return e.statusCode !== "ARCHIVED"; })
            .map(function (e) { return { eventId: String(e.eventId), label: scwin.eventLabel(e) }; }));
        sbx_event.setValue(dma_import.get("eventId") || "");
        scwin.updateCheckButton();
        scwin.loadHistory();
    }).catch(function (err) { scwin.toast("Không tải được danh sách sự kiện: " + err.message, "error"); });
};

/* ---------- Bước ---------- */
scwin.setStep = function (n) {
    scwin.step = n;
    [grp_step1, grp_step2, grp_step3].forEach(function (g, i) { scwin.show(g, i + 1 === n); });
    [grp_st1, grp_st2, grp_st3].forEach(function (g, i) {
        scwin.toggleClass(g, "is-current", i + 1 === n);
        scwin.toggleClass(g, "is-done", i + 1 < n);
    });
    window.scrollTo && window.scrollTo(0, 0);
};

/* =====================================================================
 * BƯỚC 1: CHỌN SỰ KIỆN, TẢI MẪU, CHỌN FILE
 * ===================================================================== */
scwin.sbx_event_onchange = function () {
    dma_import.set("eventId", sbx_event.getValue() || "");
    scwin.updateCheckButton();
    scwin.loadHistory();
};
scwin.btn_tplXlsx_onclick = function () { scwin.downloadFile(scwin.IMPORT_API + "/template?format=xlsx", "MauImportKhachMoi.xlsx", btn_tplXlsx); };
scwin.btn_tplCsv_onclick = function () { scwin.downloadFile(scwin.IMPORT_API + "/template?format=csv", "MauImportKhachMoi.csv", btn_tplCsv); };

scwin.initFileInput = function () {
    var inp = document.createElement("input");
    inp.type = "file";
    inp.accept = ".xlsx,.xls,.csv";
    inp.className = "gs-native-file";
    inp.addEventListener("change", function () { var f = inp.files && inp.files[0]; inp.value = ""; if (f) scwin.acceptFile(f); });
    document.body.appendChild(inp);
    scwin.fileInput = inp;
};
scwin.initDropzone = function () {
    var el = scwin.domOf(grp_drop);
    if (!el) return;
    el.addEventListener("dragover", function (e) { e.preventDefault(); grp_drop.addClass("is-dragover"); });
    el.addEventListener("dragleave", function () { grp_drop.removeClass("is-dragover"); });
    el.addEventListener("drop", function (e) {
        e.preventDefault(); grp_drop.removeClass("is-dragover");
        var f = e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files[0];
        if (f) scwin.acceptFile(f);
    });
};
scwin.grp_drop_onclick = function () { if (scwin.fileInput) scwin.fileInput.click(); };

scwin.acceptFile = function (f) {
    var ext = String(f.name.split(".").pop() || "").toLowerCase();
    scwin.show(tbx_s1Err, false);
    if (scwin.EXTS.indexOf(ext) < 0) { scwin.s1Error("Chỉ nhận file .xlsx, .xls hoặc .csv."); return; }
    if (f.size > scwin.MAX_FILE) { scwin.s1Error("File nặng " + scwin.fmtSize(f.size) + ", vượt giới hạn 10 MB."); return; }
    scwin.file = f;
    tbx_fileName.setValue(f.name);
    tbx_fileMeta.setValue(scwin.fmtSize(f.size) + ", " + ext.toUpperCase());
    scwin.show(grp_fileBar, true);
    grp_drop.addClass("has-file");
    scwin.updateCheckButton();
};
scwin.btn_fileClear_onclick = function () {
    scwin.file = null;
    scwin.show(grp_fileBar, false);
    grp_drop.removeClass("has-file");
    scwin.updateCheckButton();
};
scwin.s1Error = function (msg) { tbx_s1Err.setValue(msg); scwin.show(tbx_s1Err, true); };
scwin.updateCheckButton = function () {
    var ready = !!(scwin.file && dma_import.get("eventId"));
    try { btn_check.setDisabled(!ready); } catch (e) { }
    tbx_checkHint.setValue(!dma_import.get("eventId") ? "Chọn sự kiện nhận khách." : (!scwin.file ? "Chọn file danh sách khách." : "Sẵn sàng kiểm tra " + scwin.file.name + "."));
};

/** Gửi file lên để kiểm tra (preview). mapping = null -> server tự nhận cột theo tên. */
scwin.runPreview = function (mapping) {
    if (scwin.busy) return;
    if (!dma_import.get("eventId")) { scwin.s1Error("Chọn sự kiện trước."); return; }
    if (!scwin.file) { scwin.s1Error("Chọn file trước."); return; }
    var fd = new FormData();
    fd.append("eventId", dma_import.get("eventId"));
    fd.append("file", scwin.file);
    if (mapping) fd.append("columnMapping", JSON.stringify(mapping));
    var oldBatch = scwin.batch && !scwin.result ? scwin.batch.batchId : null;
    scwin.busy = true;
    var btn = mapping ? btn_remap : btn_check;
    btn.addClass("is-busy");
    tbx_progress.setValue("Đang tải file lên… 0%");
    scwin.show(tbx_progress, true);
    scwin.xhr("POST", scwin.IMPORT_API + "/preview", {
        body: fd,
        onProgress: function (p) { tbx_progress.setValue(p < 100 ? "Đang tải file lên… " + p + "%" : "Đang kiểm tra dữ liệu…"); }
    }).then(function (d) {
        if (oldBatch && oldBatch !== d.batchId) scwin.cancelBatch(oldBatch, true);
        scwin.batch = d;
        scwin.result = null;
        scwin.renderPreview();
        scwin.setStep(2);
    }).catch(function (err) {
        if (scwin.step === 1) scwin.s1Error(err.message);
        else { tbx_mapErr.setValue(err.message); scwin.show(tbx_mapErr, true); }
    }).then(function () {
        scwin.busy = false;
        btn.removeClass("is-busy");
        scwin.show(tbx_progress, false);
    });
};
scwin.btn_check_onclick = function () { scwin.runPreview(null); };

/* =====================================================================
 * BƯỚC 2: MAPPING CỘT & XEM TRƯỚC
 * ===================================================================== */
scwin.renderPreview = function () {
    var b = scwin.batch;
    tbx_sumTotal.setValue(scwin.fmtNumber(b.totalRows));
    tbx_sumValid.setValue(scwin.fmtNumber(b.validRows));
    tbx_sumInvalid.setValue(scwin.fmtNumber(b.invalidRows));
    tbx_previewFile.setValue(b.fileName + " vào " + scwin.eventName(b.eventId));

    // Mapping: danh sách cột đọc được trong file
    dlt_headers.setJSON((b.headers || []).map(function (h, i) { return { value: h, label: "Cột " + (i + 1) + ": " + h }; }));
    var m = b.columnMapping || {}, map = {};
    scwin.MAP_FIELDS.forEach(function (f) { map["m_" + f.key] = m[f.key] || ""; });
    map.eventId = dma_import.get("eventId");
    map.skipErrors = dma_import.get("skipErrors");
    dma_import.setJSON(map);
    var un = (b.unmappedFields || []).map(function (k) { return scwin.fieldLabel(k); });
    tbx_unmapped.setValue(un.length ? "Chưa tìm thấy cột cho: " + un.join(", ") + ". Chọn cột tương ứng bên dưới nếu file có các thông tin này." : "");
    scwin.show(tbx_unmapped, un.length > 0);
    scwin.show(tbx_mapErr, false);

    scwin.setRowFilter(b.invalidRows ? "invalid" : "all");
    scwin.updateConfirm();
};

scwin.fieldLabel = function (k) { for (var i = 0; i < scwin.MAP_FIELDS.length; i++) if (scwin.MAP_FIELDS[i].key === k) return scwin.MAP_FIELDS[i].label; return k; };
scwin.eventName = function (id) {
    for (var i = 0; i < scwin.lookups.events.length; i++) if (String(scwin.lookups.events[i].eventId) === String(id)) return scwin.lookups.events[i].eventName;
    return "sự kiện #" + id;
};

scwin.setRowFilter = function (f) {
    scwin.rowFilter = f;
    scwin.toggleClass(btn_rfAll, "is-selected", f === "all");
    scwin.toggleClass(btn_rfValid, "is-selected", f === "valid");
    scwin.toggleClass(btn_rfInvalid, "is-selected", f === "invalid");
    var b = scwin.batch;
    btn_rfAll.setValue("Tất cả (" + scwin.fmtNumber(b.totalRows) + ")");
    btn_rfValid.setValue("Hợp lệ (" + scwin.fmtNumber(b.validRows) + ")");
    btn_rfInvalid.setValue("Có lỗi (" + scwin.fmtNumber(b.invalidRows) + ")");
    var rows = (b.rows || []).filter(function (r) { return f === "all" || (f === "valid" ? r.valid : !r.valid); });
    dlt_rows.setJSON(rows.map(function (r) {
        var d = r.data || {};
        return {
            rowNumber: String(r.rowNumber), valid: r.valid ? "1" : "0",
            fullName: d.fullName || "", email: d.email || "", phone: d.phone || "", company: d.company || "",
            position: d.position || "", guestType: d.guestType || "", tableNumber: d.tableNumber || "", notes: d.notes || "",
            errorText: (r.errors || []).map(function (e) { return e.message; }).join("; ")
        };
    }));
    for (var i = 0; i < rows.length; i++) {
        try { grd_rows.setCellClass(i, "valid", rows[i].valid ? "gs-rowok" : "gs-rowbad"); } catch (e) { }
    }
    scwin.show(grp_rowsEmpty, !rows.length);
    tbx_rowsEmpty.setValue(f === "invalid" ? "Không có dòng lỗi nào." : "Không có dòng nào.");
};
scwin.btn_rfAll_onclick = function () { scwin.setRowFilter("all"); };
scwin.btn_rfValid_onclick = function () { scwin.setRowFilter("valid"); };
scwin.btn_rfInvalid_onclick = function () { scwin.setRowFilter("invalid"); };

scwin.gfValid = function (v) { return v === "1" ? "● Hợp lệ" : "● Lỗi"; };
scwin.gfRow = function (v) { return "Dòng " + v; };
scwin.gfDash = function (v) { return scwin.dash(v); };

/** Mapping đang chọn: field -> tên cột (rỗng = không nhập). */
scwin.currentMapping = function () {
    var m = {};
    scwin.MAP_FIELDS.forEach(function (f) {
        var c = scwin.comp("sbx_m_" + f.key);
        var v = c ? c.getValue() : dma_import.get("m_" + f.key);
        m[f.key] = v || "";
    });
    return m;
};
scwin.btn_remap_onclick = function () {
    var m = scwin.currentMapping();
    var missing = scwin.MAP_FIELDS.filter(function (f) { return f.required && !m[f.key]; }).map(function (f) { return f.label; });
    if (missing.length) { tbx_mapErr.setValue("Cần chọn cột cho: " + missing.join(", ") + "."); scwin.show(tbx_mapErr, true); return; }
    var used = {}, dup = [];
    for (var k in m) if (m[k]) { if (used[m[k]]) dup.push(m[k]); used[m[k]] = true; }
    if (dup.length) { tbx_mapErr.setValue("Cột “" + dup[0] + "” đang được chọn cho nhiều thông tin."); scwin.show(tbx_mapErr, true); return; }
    scwin.runPreview(m);
};
scwin.mapping_onchange = function () { scwin.show(tbx_mapErr, false); grp_mapping.addClass("is-dirty"); };

scwin.updateConfirm = function () {
    var b = scwin.batch;
    if (!b) return;
    var skip = !!String(chk_skip.getValue() || "");
    var n = skip || !b.invalidRows ? b.validRows : 0;
    btn_confirm.setValue(n ? "Import " + scwin.fmtNumber(n) + " khách" : "Import khách");
    var blocked = !b.validRows || (b.invalidRows && !skip);
    try { btn_confirm.setDisabled(!!blocked); } catch (e) { }
    tbx_confirmHint.setValue(!b.validRows ? "File không có dòng hợp lệ nào để import."
        : b.invalidRows && !skip ? "Còn " + scwin.fmtNumber(b.invalidRows) + " dòng lỗi. Sửa file rồi kiểm tra lại, hoặc tích “Bỏ qua dòng lỗi”."
        : "Mỗi khách được tạo ở trạng thái Đã mời và có sẵn mã QR cá nhân.");
    scwin.toggleClass(tbx_confirmHint, "is-warning", !!blocked);
    scwin.show(btn_errCsv, b.invalidRows > 0);
};
scwin.chk_skip_onchange = function () { dma_import.set("skipErrors", chk_skip.getValue() || ""); scwin.updateConfirm(); };

/** Tải danh sách dòng lỗi (tạo CSV ngay trên trình duyệt từ kết quả kiểm tra). */
scwin.btn_errCsv_onclick = function () {
    var b = scwin.batch;
    var q = function (s) { s = String(s == null ? "" : s); return /[",\n;]/.test(s) ? "\"" + s.replace(/"/g, "\"\"") + "\"" : s; };
    var lines = ["Dòng,Cột,Mã lỗi,Mô tả lỗi,Họ tên,Email,Điện thoại"];
    (b.rows || []).forEach(function (r) {
        if (r.valid) return;
        var d = r.data || {};
        (r.errors || []).forEach(function (e) { lines.push([r.rowNumber, e.column, e.code, e.message, d.fullName, d.email, d.phone].map(q).join(",")); });
    });
    scwin.saveBlob(new Blob(["\ufeff" + lines.join("\r\n")], { type: "text/csv;charset=utf-8" }), "LoiImport-" + (b.fileName || "file").replace(/\.[^.]+$/, "") + ".csv");
};

scwin.btn_back_onclick = function () {
    if (scwin.batch && !scwin.result) scwin.cancelBatch(scwin.batch.batchId, true);
    scwin.batch = null;
    scwin.setStep(1);
};
scwin.cancelBatch = function (batchId, silent) {
    return scwin.callApi("sbm_cancelBatch", { url: scwin.IMPORT_API + "/" + batchId + "/cancel" })
        .catch(function (err) { if (!silent) scwin.toast(err.message, "error"); });
};

scwin.btn_confirm_onclick = function () {
    var b = scwin.batch;
    if (!b || scwin.busy) return;
    var skip = !!String(chk_skip.getValue() || "");
    scwin.busy = true;
    btn_confirm.addClass("is-busy");
    scwin.callApi("sbm_confirm", { url: scwin.IMPORT_API + "/" + b.batchId + "/confirm", body: { skipErrors: skip } }).then(function (r) {
        scwin.result = r;
        scwin.renderResult();
        scwin.setStep(3);
        scwin.loadHistory();
    }).catch(function (err) {
        if (err.code === "IMPORT_ALREADY_PROCESSED") { scwin.toast(err.message + " Hãy kiểm tra lại file.", "warning"); scwin.btn_back_onclick(); return; }
        scwin.toast(err.message, "error");
    }).then(function () { scwin.busy = false; btn_confirm.removeClass("is-busy"); });
};

/* =====================================================================
 * BƯỚC 3: KẾT QUẢ
 * ===================================================================== */
scwin.renderResult = function () {
    var r = scwin.result;
    tbx_resSuccess.setValue(scwin.fmtNumber(r.successRows));
    tbx_resFailed.setValue(scwin.fmtNumber(r.failedRows));
    tbx_resTotal.setValue(scwin.fmtNumber(r.totalRows));
    var all = r.successRows === r.totalRows;
    tbx_resTitle.setValue(r.successRows ? (all ? "Import thành công toàn bộ danh sách" : "Đã import " + scwin.fmtNumber(r.successRows) + "/" + scwin.fmtNumber(r.totalRows) + " khách") : "Không có khách nào được import");
    tbx_resDesc.setValue("File " + r.fileName + " vào " + (r.eventCode ? r.eventCode + " " : "") + scwin.eventName(r.eventId)
        + ", lúc " + scwin.fmtDateTime(r.importedAt) + (r.importedByName ? " bởi " + r.importedByName : "") + ".");
    scwin.toggleClass(grp_result, "is-partial", !all);
    scwin.show(grp_resErrors, r.errorCount > 0 || r.failedRows > 0);
};
scwin.errorFileUrl = function (batchId, format) { return scwin.IMPORT_API + "/batches/" + batchId + "/errors/file?format=" + format; };
scwin.btn_resErrXlsx_onclick = function () { scwin.downloadFile(scwin.errorFileUrl(scwin.result.batchId, "xlsx"), "LoiImport-" + scwin.result.batchId + ".xlsx", btn_resErrXlsx); };
scwin.btn_resErrCsv_onclick = function () { scwin.downloadFile(scwin.errorFileUrl(scwin.result.batchId, "csv"), "LoiImport-" + scwin.result.batchId + ".csv", btn_resErrCsv); };
scwin.btn_viewGuests_onclick = function () {
    window.location.href = scwin.pageUrl(scwin.LIST_PAGE, { eventId: scwin.result.eventId, importBatchId: scwin.result.batchId });
};
scwin.btn_again_onclick = function () {
    scwin.batch = null; scwin.result = null;
    scwin.btn_fileClear_onclick();
    scwin.setStep(1);
};
scwin.btn_toList_onclick = function () { window.location.href = scwin.pageUrl(scwin.LIST_PAGE, { eventId: dma_import.get("eventId") }); };

/* =====================================================================
 * LỊCH SỬ IMPORT CỦA SỰ KIỆN
 * ===================================================================== */
scwin.loadHistory = function () {
    var eventId = dma_import.get("eventId");
    if (!eventId) { dlt_batches.setJSON([]); scwin.fitGrid(grd_batches, 0); tbx_histEmpty.setValue("Chọn sự kiện để xem các lần import trước."); scwin.show(grp_histEmpty, true); return; }
    scwin.callApi("sbm_batches", { url: scwin.IMPORT_API + "/batches?" + scwin.buildQuery({ eventId: eventId, page: 0, size: 10 }) }).then(function (page) {
        if (dma_import.get("eventId") !== eventId) return;
        var list = (page && page.content) || [];
        dlt_batches.setJSON(list.map(function (b) {
            var c = {}; for (var k in b) if (b.hasOwnProperty(k)) c[k] = b[k];
            c.actErrors = ""; c.actGuests = ""; return c;
        }));
        for (var i = 0; i < list.length; i++) { try { grd_batches.setCellClass(i, "status", "gs-bst gs-bst--" + list[i].status); } catch (e) { } }
        scwin.fitGrid(grd_batches, list.length, 48);
        tbx_histEmpty.setValue("Sự kiện chưa có lần import nào.");
        scwin.show(grp_histEmpty, !list.length);
    }).catch(function () { });
};
scwin.gfBatchStatus = function (v) { return "● " + (scwin.BATCH_STATUS_VN[v] || v); };
scwin.gfBatchCount = function (v, f, i) {
    var b = dlt_batches.getRowJSON(i) || {};
    return scwin.fmtNumber(b.successRows) + " / " + scwin.fmtNumber(b.totalRows);
};
scwin.gfBatchErr = function (v, f, i) { var b = dlt_batches.getRowJSON(i) || {}; return Number(b.errorCount || b.failedRows) > 0 ? "Tải log lỗi" : ""; };
scwin.gfBatchGuests = function (v, f, i) { var b = dlt_batches.getRowJSON(i) || {}; return Number(b.successRows) > 0 ? "Xem khách" : ""; };
scwin.gfDateTime = function (v) { return v ? scwin.fmtDateTime(v) : "—"; };
scwin.grd_batches_oncellclick = function (rowIndex, colIndex, colId) {
    var b = dlt_batches.getRowJSON(rowIndex) || {};
    if (colId === "actErrors" && Number(b.errorCount || b.failedRows) > 0) scwin.downloadFile(scwin.errorFileUrl(b.batchId, "xlsx"), "LoiImport-" + b.batchId + ".xlsx");
    if (colId === "actGuests" && Number(b.successRows) > 0) window.location.href = scwin.pageUrl(scwin.LIST_PAGE, { eventId: b.eventId, importBatchId: b.batchId });
};

/* Handler gắn trong xf:submission (ev:submitdone / ev:submiterror) */
scwin.sbm_lookups_submitdone = function (e) { scwin.onSbmDone("sbm_lookups", e); };
scwin.sbm_lookups_submiterror = function (e) { scwin.onSbmError("sbm_lookups", e); };
scwin.sbm_confirm_submitdone = function (e) { scwin.onSbmDone("sbm_confirm", e); };
scwin.sbm_confirm_submiterror = function (e) { scwin.onSbmError("sbm_confirm", e); };
scwin.sbm_cancelBatch_submitdone = function (e) { scwin.onSbmDone("sbm_cancelBatch", e); };
scwin.sbm_cancelBatch_submiterror = function (e) { scwin.onSbmError("sbm_cancelBatch", e); };
scwin.sbm_batches_submitdone = function (e) { scwin.onSbmDone("sbm_batches", e); };
scwin.sbm_batches_submiterror = function (e) { scwin.onSbmError("sbm_batches", e); };
scwin.sbm_batchErrors_submitdone = function (e) { scwin.onSbmDone("sbm_batchErrors", e); };
scwin.sbm_batchErrors_submiterror = function (e) { scwin.onSbmError("sbm_batchErrors", e); };
